with flagged as (select *, case when lag(reading_ts) over (partition by device_code order by reading_ts, id) is null or reading_ts > lag(reading_ts) over (partition by device_code order by reading_ts, id) + interval '20' minute then 1 else 0 end as is_new_session from device_readings), sessionized as (select *, sum(is_new_session) over (partition by device_code order by reading_ts, id rows between unbounded preceding and current row) as session_id from flagged) select device_code, bit_or(status_bits) as status_bits_bit_or, approx_percentile(is_new_session, 0.9) as is_new_session_p90, round(sum(session_id) / nullif(count(case when device_code = 'DV-03' then 1 end), 0), 2) as session_id_per_dv_03, stddev_samp(humidity) as humidity_stddev, count(case when device_code = 'DV-02' then 1 end) as dv_02_count, sum(case when device_code = 'DV-03' then is_new_session else 0 end) as dv_03_is_new_session from sessionized group by device_code having approx_percentile(is_new_session, 0.9) > 0 order by dv_03_is_new_session desc nulls last
